('learn-operating-systems-cpu-scheduling-check',1,'learn-operating-systems-cpu-scheduling-core',1,'numeric_answer','Scheduling and waiting time · Check your understanding','For FCFS P1=(arrival 0, burst 5), P2=(1,3), P3=(2,1), what is P2 waiting time?','[]','medium',180,'published'),
('learn-operating-systems-synchronization-check',1,'learn-operating-systems-synchronization-core',1,'multiple_choice','Mutex and critical sections · Check your understanding','A shared balance uses check-then-update. What needs protection?','["Only the final write","The related read and write","Only logging"]','medium',120,'published'),
('learn-operating-systems-deadlocks-check',1,'learn-operating-systems-deadlocks-core',1,'multiple_choice','Deadlock conditions · Check your understanding','Which strategy prevents circular wait for multiple locks?','["Acquire locks in a global order","Increase thread count","Ignore the wait"]','medium',120,'published'),
('learn-networks-tcp-check',1,'learn-networks-tcp-core',1,'ordering','TCP three-way handshake · Check your understanding','Arrange the normal handshake messages.','["Server SYN-ACK","Client ACK","Client SYN"]','easy',120,'published'),
