('learn-aptitude-time-work-check',1,'4','1/12 + 1/6 = 1/4 of a job per day, so four days.'),
('learn-aptitude-speed-time-distance-check',1,'48','For equal distances the average is 2ab/(a+b) = 4800/100 = 48.'),
('learn-java-fundamentals-check',1,'"No"','Only the copied reference value in the parameter was reassigned.'),
('learn-java-oop-check',1,'"Dog"','The runtime object is Dog; overridden instance methods dispatch dynamically.'),
('learn-java-collections-framework-check',1,'"LinkedHashSet"','LinkedHashSet preserves encounter order while enforcing set uniqueness.'),
('learn-java-exceptions-check',1,'"IOException"','IOException is checked; the other two extend RuntimeException.'),
('learn-java-generics-check',1,'"No"','The list could be a List<Double>. The extends bound supports reading as Number, not adding an arbitrary Number.'),
('learn-sql-dbms-fundamentals-check',1,'"manager_id IS NULL"','SQL uses IS NULL to test for NULL; equality produces unknown.'),
('learn-sql-dbms-joins-check',1,'2','A matches its order. B remains with NULL order columns, giving two rows.'),
('learn-sql-dbms-aggregation-check',1,'"HAVING"','HAVING filters aggregate groups; WHERE filters individual input rows.'),
('learn-sql-dbms-normalization-check',1,'"Transitive dependency"','The non-key department name depends on the employee key through department_id.'),
('learn-sql-dbms-transactions-check',1,'"Lost update"','B overwrites A’s update using an earlier value rather than incorporating it.'),
('learn-operating-systems-processes-check',1,'"Each process"','A process is the usual unit of virtual address-space isolation.'),
('learn-operating-systems-threads-check',1,'"Its stack"','Each thread keeps its own call stack and execution context.'),
('learn-operating-systems-cpu-scheduling-check',1,'4','P2 waits from arrival 1 until it starts at 5: four units.'),
('learn-operating-systems-synchronization-check',1,'"The related read and write"','Protecting only the write leaves the check vulnerable to an interleaving.'),
('learn-operating-systems-deadlocks-check',1,'"Acquire locks in a global order"','A consistent total ordering prevents a cycle in lock acquisition.'),
('learn-networks-tcp-check',1,'["Client SYN","Server SYN-ACK","Client ACK"]','The server acknowledges the client SYN and sends its own. The final ACK acknowledges that SYN.'),
('learn-networks-dns-check',1,'"How long a record may be cached"','TTL controls cache lifetime for the DNS record; it is not an HTTP or TCP setting.'),
('learn-networks-http-check',1,'"Repeated idempotent requests have the same intended effect"','Idempotency describes the intended effect, not identical responses.'),
