-- Learn extends canonical tracks/topics. It does not own a second attempt or retention engine.
create table public.learning_subjects(id text primary key,name text not null,track_id text not null references public.tracks(id),tagline text not null,icon text not null,sort_order integer not null);
create index learning_subject_track on public.learning_subjects(track_id);
create table public.learning_topic_catalog(topic_id text primary key references public.topics(id),subject_id text not null references public.learning_subjects(id),sort_order integer not null);
create index learning_topic_subject on public.learning_topic_catalog(subject_id,sort_order,topic_id);
create table public.learning_concepts(
 id text not null,version integer not null check(version>0),topic_id text not null references public.topics(id),name text not null,sort_order integer not null,
 status text not null check(status in ('draft','review','published','deprecated','archived')),
 summary text not null default '' check(length(summary)<=4000),mental_model text not null default '' check(length(mental_model)<=4000),worked_example text not null default '' check(length(worked_example)<=6000),
 misconception text not null default '' check(length(misconception)<=2000),interview_prompt text not null default '',interview_answer text not null default '',
 diagram text check(diagram in ('transaction','scheduler','runtime','request')),source_reference text not null,source_type text not null default 'original',author text not null,reviewer text not null,reviewed_at date,
 language_version text,primary key(id,version),check(status<>'published' or (length(summary)>20 and reviewed_at is not null))
);
create index learning_concept_topic on public.learning_concepts(topic_id,status,sort_order,id,version desc);
create index learning_concept_search on public.learning_concepts using gin(to_tsvector('english',name||' '||summary)) where status='published';
create table public.learning_concept_relations(from_id text not null,from_version integer not null,to_id text not null,to_version integer not null,relation_type text not null check(relation_type in ('prerequisite','related','compare_with','builds_on')),primary key(from_id,from_version,to_id,to_version,relation_type),check(from_id<>to_id),foreign key(from_id,from_version) references public.learning_concepts(id,version),foreign key(to_id,to_version) references public.learning_concepts(id,version));
create index learning_relation_target on public.learning_concept_relations(to_id,to_version);
create table public.learning_activities(
 id text not null,version integer not null,concept_id text not null,concept_version integer not null,
 activity_type text not null check(activity_type in ('multiple_choice','multiple_select','numeric_answer','short_answer','true_false','code_exercise','sql_exercise','scenario','ordering','matching','interview_question','concept_review')),
 title text not null,prompt text not null check(length(prompt)<=12000),options jsonb not null default '[]' check(jsonb_typeof(options)='array' and jsonb_array_length(options)<=20),
 difficulty text not null check(difficulty in ('easy','medium','hard')),estimated_seconds integer check(estimated_seconds between 30 and 3600),
 status text not null check(status in ('draft','review','published','deprecated','archived')),primary key(id,version),foreign key(concept_id,concept_version) references public.learning_concepts(id,version)
);
create index learning_activity_concept on public.learning_activities(concept_id,concept_version,status);
create table private.learning_answer_keys(activity_id text not null,activity_version integer not null,answer jsonb not null,solution text not null check(length(solution)<=6000),tolerance numeric not null default 0 check(tolerance between 0 and 1),primary key(activity_id,activity_version),foreign key(activity_id,activity_version) references public.learning_activities(id,version));
revoke all on private.learning_answer_keys from public,anon,authenticated,service_role;
create table public.workspace_learning_state(
 workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,concept_id text not null,concept_version integer not null,
 opened_at timestamptz not null default now(),bookmarked boolean not null default false,note text not null default '' check(length(note)<=4000),version integer not null default 0,
 request_id uuid not null,request_hash text not null,primary key(workspace_id,user_id,concept_id),foreign key(concept_id,concept_version) references public.learning_concepts(id,version)
);
create index learning_state_concept on public.workspace_learning_state(concept_id,concept_version);
create index learning_state_recent on public.workspace_learning_state(workspace_id,user_id,opened_at desc);
-- A binding, not another attempt model. Timers and evidence remain Execution-owned.
create table public.learning_execution_bindings(
 session_id uuid primary key,item_id uuid not null unique,workspace_id uuid not null,user_id uuid not null,activity_id text not null,activity_version integer not null,
 answer jsonb,confidence integer check(confidence between 1 and 5),submitted_at timestamptz,correct boolean,timed_out boolean not null default false,submit_hash text,
 foreign key(item_id,session_id,workspace_id,user_id) references public.execution_session_items(id,session_id,workspace_id,user_id) on delete cascade,
 foreign key(activity_id,activity_version) references public.learning_activities(id,version),check(answer is null or octet_length(answer::text)<=6000)
);
create index learning_binding_owner on public.learning_execution_bindings(workspace_id,user_id,activity_id,submitted_at desc);
create index learning_binding_activity on public.learning_execution_bindings(activity_id,activity_version);
do $$declare t text;begin
 foreach t in array array['learning_subjects','learning_topic_catalog','learning_concepts','learning_concept_relations','learning_activities'] loop
 execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);
 end loop;
 foreach t in array array['workspace_learning_state','learning_execution_bindings'] loop
 execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);
 execute format('create policy learning_owner_read on public.%I for select to authenticated using(user_id=(select auth.uid()) and public.is_workspace_member(workspace_id))',t);
 end loop;
end $$;
create policy learning_subject_read on public.learning_subjects for select to authenticated using(true);
create policy learning_topic_read on public.learning_topic_catalog for select to authenticated using(true);
create policy learning_concept_read on public.learning_concepts for select to authenticated using(status='published');
create policy learning_activity_read on public.learning_activities for select to authenticated using(status='published' and exists(select 1 from public.learning_concepts c where c.id=concept_id and c.version=concept_version and c.status='published'));
create policy learning_relation_read on public.learning_concept_relations for select to authenticated using(exists(select 1 from public.learning_concepts where id=from_id and version=from_version) and exists(select 1 from public.learning_concepts where id=to_id and version=to_version));
create function private.learning_content_immutable() returns trigger language plpgsql set search_path='' as $$begin
 if old.status in ('published','deprecated','archived') and ((to_jsonb(new)-'status')<>(to_jsonb(old)-'status') or new.status not in ('published','deprecated','archived')) then raise exception 'Publish a new content version' using errcode='22023';end if;return new;end $$;
revoke all on function private.learning_content_immutable() from public,anon,authenticated,service_role;
create trigger learning_concept_version before update on public.learning_concepts for each row execute function private.learning_content_immutable();
create trigger learning_activity_version before update on public.learning_activities for each row execute function private.learning_content_immutable();


create function private.learning_prerequisite_acyclic() returns trigger language plpgsql set search_path='' as $$begin
 if new.relation_type='prerequisite' and exists(with recursive path(id) as(select new.to_id union select r.to_id from public.learning_concept_relations r join path p on r.from_id=p.id where r.relation_type='prerequisite') select 1 from path where id=new.from_id) then raise exception 'Prerequisites cannot form a cycle' using errcode='22023';end if;return new;end $$;
revoke all on function private.learning_prerequisite_acyclic() from public,anon,authenticated,service_role;
create trigger learning_prerequisite_graph before insert or update on public.learning_concept_relations for each row execute function private.learning_prerequisite_acyclic();

create function private.learning_key_immutable() returns trigger language plpgsql set search_path='' as $$begin
 if exists(select 1 from public.learning_activities where id=old.activity_id and version=old.activity_version and status in ('published','deprecated','archived')) then raise exception 'Publish a new activity version to change its answer key' using errcode='22023';end if;if tg_op='DELETE' then return old;end if;return new;end $$;
revoke all on function private.learning_key_immutable() from public,anon,authenticated,service_role;
create trigger learning_key_version before update or delete on private.learning_answer_keys for each row execute function private.learning_key_immutable();

-- Library browsing is optional enrichment. Explicit template exclusions still govern attribution.
create or replace function private.execution_topic_allowed(p_workspace uuid,p_topic text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.topics t where t.id=p_topic and t.is_active and (
 exists(select 1 from public.template_version_topics vt where vt.topic_id=t.id and vt.template_version_id=coalesce((select template_version_id from public.workspace_curricula where workspace_id=p_workspace),(select v.id from public.workspace_targets wt join public.preparation_template_versions v on v.template_id=wt.template_id and v.version_number=coalesce(wt.template_version,1) where wt.workspace_id=p_workspace)))
 or exists(select 1 from public.learning_topic_catalog l where l.topic_id=t.id))
 and not exists(select 1 from public.workspace_curriculum_overrides o where o.workspace_id=p_workspace and o.override_type='inclusion' and o.value->>'included'='false' and ((o.entity_type='topic' and o.entity_id=t.id) or (o.entity_type='track' and o.entity_id=t.track_id))))
$$;

create function private.learning_catalog(p_slug text,p_subject text default 'aptitude',p_topic text default null,p_search text default '',p_after text default '',p_bookmarked boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;topics_json jsonb;concepts_json jsonb;begin
 w:=private.revision_access(p_slug);
 if length(p_search)>120 or length(p_after)>200 or length(p_subject)>50 then raise exception 'Invalid learning filters' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by sort_order,topic_id),'[]') into topics_json from(
 select l.*,t.name,(select count(distinct id) from public.learning_concepts where topic_id=t.id) as planned_count,(select count(distinct id) from public.learning_concepts where topic_id=t.id and status='published') as published_count,private.execution_topic_allowed(w.id,t.id) as included
 from public.learning_topic_catalog l join public.topics t on t.id=l.topic_id where l.subject_id=p_subject order by l.sort_order,l.topic_id limit 80) x;
 select coalesce(jsonb_agg(to_jsonb(x) order by id),'[]') into concepts_json from (
 select distinct on(c.id) c.id,c.version,c.topic_id,c.name,c.status,c.sort_order,l.subject_id,t.name as topic_name,
 case when c.status='published' then c.summary else '' end as summary,
 coalesce(st.bookmarked,false) as bookmarked,st.opened_at,
 (select count(*) from public.learning_execution_bindings b join public.learning_activities a on a.id=b.activity_id and a.version=b.activity_version where b.workspace_id=w.id and b.user_id=(select auth.uid()) and a.concept_id=c.id and b.submitted_at is not null) as attempts,
 (select r.id from public.learning_execution_bindings b join public.learning_activities a on a.id=b.activity_id and a.version=b.activity_version join public.revision_items r on r.entity_id=b.item_id where b.workspace_id=w.id and b.user_id=(select auth.uid()) and a.concept_id=c.id and r.state in ('scheduled','snoozed') order by r.created_at limit 1) as revision_id
 from public.learning_concepts c join public.learning_topic_catalog l on l.topic_id=c.topic_id join public.topics t on t.id=c.topic_id
 left join public.workspace_learning_state st on st.workspace_id=w.id and st.user_id=(select auth.uid()) and st.concept_id=c.id
 where ((p_bookmarked and st.bookmarked and c.status='published') or (not p_bookmarked and ((p_search='' and l.subject_id=p_subject and c.topic_id=coalesce(p_topic,(topics_json->0->>'topic_id'))) or (p_search<>'' and c.status='published' and (to_tsvector('english',c.name||' '||c.summary)@@websearch_to_tsquery('english',p_search) or c.name ilike '%'||p_search||'%' or t.name ilike '%'||p_search||'%' or exists(select 1 from public.learning_subjects ls where ls.id=l.subject_id and ls.name ilike '%'||p_search||'%') or exists(select 1 from public.learning_activities la where la.concept_id=c.id and la.concept_version=c.version and la.status='published' and la.prompt ilike '%'||p_search||'%'))))))
 and c.id>p_after order by c.id,(c.status='published') desc,c.version desc limit 61) x;
 return jsonb_build_object('workspace',jsonb_build_object('id',w.id,'slug',w.slug,'userId',(select auth.uid()),'canEdit',w.status='active'),'subjects',(select jsonb_agg(to_jsonb(s)||jsonb_build_object('published_count',(select count(distinct c.id) from public.learning_concepts c join public.learning_topic_catalog t on t.topic_id=c.topic_id where t.subject_id=s.id and c.status='published')) order by s.sort_order) from public.learning_subjects s),'topics',topics_json,'concepts',concepts_json,'serverNow',now());
end $$;
create function private.learning_concept(p_slug text,p_id text) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;c public.learning_concepts%rowtype;begin
 w:=private.revision_access(p_slug);select * into c from public.learning_concepts where id=p_id and status='published' order by version desc limit 1;
 if c.id is null then raise exception 'Published lesson unavailable' using errcode='22023';end if;
 return jsonb_build_object('concept',to_jsonb(c),'activities',coalesce((select jsonb_agg(to_jsonb(a)) from public.learning_activities a where a.concept_id=c.id and a.concept_version=c.version and a.status='published'),'[]'),
 'state',(select to_jsonb(s) from public.workspace_learning_state s where workspace_id=w.id and user_id=(select auth.uid()) and concept_id=c.id),
 'revision',(select jsonb_build_object('id',r.id,'due_at',r.due_at,'interval_days',r.interval_days,'state',r.state) from public.revision_items r join public.learning_execution_bindings b on b.item_id=r.entity_id join public.learning_activities a on a.id=b.activity_id and a.version=b.activity_version where r.workspace_id=w.id and r.user_id=(select auth.uid()) and a.concept_id=c.id and r.state in ('scheduled','snoozed') order by r.due_at limit 1),
 'relations',coalesce((select jsonb_agg(jsonb_build_object('id',z.id,'name',z.name,'type',r.relation_type)) from public.learning_concept_relations r join public.learning_concepts z on z.id=r.to_id and z.version=r.to_version and z.status='published' where r.from_id=c.id and r.from_version=c.version),'[]'));
end $$;
create function private.learning_state(p_slug text,p_id text,p_version integer,p_request uuid,p_patch jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;c public.learning_concepts%rowtype;s public.workspace_learning_state%rowtype;begin
 w:=private.revision_access(p_slug,true);select * into c from public.learning_concepts where id=p_id and status='published' order by version desc limit 1;
 if c.id is null or p_request is null or jsonb_typeof(p_patch)<>'object' or octet_length(p_patch::text)>30000 or length(coalesce(p_patch->>'note',''))>4000 or exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('note','bookmarked','opened')) then raise exception 'Invalid learning state' using errcode='22023';end if;
 select * into s from public.workspace_learning_state where workspace_id=w.id and user_id=(select auth.uid()) and concept_id=c.id for update;
 if s.request_id=p_request then if s.request_hash<>md5(p_patch::text) then raise exception 'Changed learning request' using errcode='40001';end if;return to_jsonb(s);end if;
 if coalesce(s.version,-1) is distinct from p_version then raise exception 'Learning notes changed; refresh before saving' using errcode='40001';end if;
 values(w.id,(select auth.uid()),c.id,c.version,coalesce((p_patch->>'bookmarked')::boolean,false),coalesce(p_patch->>'note',''),p_request,md5(p_patch::text))
 on conflict(workspace_id,user_id,concept_id) do update set concept_version=c.version,bookmarked=coalesce((p_patch->>'bookmarked')::boolean,workspace_learning_state.bookmarked),note=coalesce(p_patch->>'note',workspace_learning_state.note),opened_at=case when p_patch->>'opened'='true' then now() else workspace_learning_state.opened_at end,version=workspace_learning_state.version+1,request_id=p_request,request_hash=md5(p_patch::text) returning * into s;return to_jsonb(s);
end $$;
create function private.learning_session(p_slug text,p_session uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;b public.learning_execution_bindings%rowtype;snapshot jsonb;begin
 w:=private.revision_access(p_slug);select * into b from public.learning_execution_bindings where session_id=p_session and workspace_id=w.id and user_id=(select auth.uid());
 if b.session_id is null then raise exception 'Learning session unavailable' using errcode='42501';end if;
 snapshot:=private.resolve_execution(p_slug,p_session);
 return jsonb_build_object('execution',snapshot,'binding',to_jsonb(b),'activity',(select to_jsonb(a) from public.learning_activities a where a.id=b.activity_id and a.version=b.activity_version),
 'feedback',case when b.submitted_at is not null then (select jsonb_build_object('answer',answer,'solution',solution) from private.learning_answer_keys where activity_id=b.activity_id and activity_version=b.activity_version) else null end);
end $$;
create function private.learning_launch(p_slug text,p_activity text,p_mode text,p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;a public.learning_activities%rowtype;c public.learning_concepts%rowtype;response jsonb;sid uuid;iid uuid;existing public.learning_execution_bindings%rowtype;origin uuid;begin
 w:=private.revision_access(p_slug,true);if p_mode is null or p_mode not in ('practice','timed') or p_request is null then raise exception 'Choose a learning mode' using errcode='22023';end if;
 select * into a from public.learning_activities where id=p_activity and status='published' order by version desc limit 1;
 select * into c from public.learning_concepts where id=a.concept_id and version=a.concept_version and status='published';
 if a.id is null or c.id is null or a.activity_type not in ('multiple_choice','multiple_select','numeric_answer','true_false','scenario','ordering','matching') then raise exception 'This activity does not have an available evaluator' using errcode='22023';end if;
 if not private.execution_topic_allowed(w.id,c.topic_id) then raise exception 'This topic is excluded from your workspace curriculum' using errcode='22023';end if;
 response:=private.create_execution(p_slug,p_request,jsonb_build_object('mode',case when p_mode='timed' then 'oa' else 'practice' end,'source','manual','targetSeconds',greatest(60,a.estimated_seconds),'prompts',jsonb_build_array(jsonb_build_object('title',a.title,'body',a.prompt||case when jsonb_array_length(a.options)>0 then E'\nOptions: '||a.options::text else '' end,'topic',c.name,'topicId',c.topic_id,'difficulty',a.difficulty,'constraints','','examples','[]'::jsonb,'hints','[]'::jsonb))));
 sid:=(response->'data'->'session'->>'id')::uuid;iid:=(response->'data'->'items'->0->>'id')::uuid;
 if not (response->>'ok')::boolean then return jsonb_build_object('otherActive',true,'sessionId',sid);end if;
 select * into existing from public.learning_execution_bindings where session_id=sid;
 if existing.session_id is not null then if existing.activity_id<>a.id then raise exception 'Changed learning launch' using errcode='40001';end if;return jsonb_build_object('sessionId',sid);end if;
 -- Repeated practice of one activity is recall evidence for one stable identity.
 select r.id into origin from public.learning_execution_bindings b join public.revision_items r on r.entity_id=b.item_id where b.workspace_id=w.id and b.user_id=(select auth.uid()) and b.activity_id=a.id order by b.submitted_at limit 1;
 if origin is not null then insert into public.revision_execution_links(item_id,session_id,revision_item_id,workspace_id,user_id) values(iid,sid,origin,w.id,(select auth.uid()));end if;
 return jsonb_build_object('sessionId',sid);
end $$;
create function private.learning_submit(p_slug text,p_session uuid,p_version integer,p_answer jsonb,p_confidence integer,p_mistakes text[] default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;b public.learning_execution_bindings%rowtype;a public.learning_activities%rowtype;k private.learning_answer_keys%rowtype;s public.execution_sessions%rowtype;response jsonb;aid uuid;answer_correct boolean;expired boolean;submission_hash text;begin
 w:=private.revision_access(p_slug,true);select * into b from public.learning_execution_bindings where session_id=p_session and workspace_id=w.id and user_id=(select auth.uid()) for update;
 if b.session_id is null then raise exception 'Learning attempt unavailable' using errcode='42501';end if;
 if p_confidence not between 1 and 5 or p_confidence is null or p_answer is null or octet_length(p_answer::text)>6000 then raise exception 'Check the answer and confidence' using errcode='22023';end if;
 if p_mistakes is null or cardinality(p_mistakes)>3 or not p_mistakes<@array['recognition','logic','syntax','edge_case','complexity','forgotten_concept','communication','time_management']::text[] or cardinality(p_mistakes)<>(select count(distinct v) from unnest(p_mistakes) v) then raise exception 'Choose valid mistake categories' using errcode='22023';end if;
 submission_hash:=md5(p_answer::text||':'||p_confidence::text||':'||p_mistakes::text);
 if b.submitted_at is not null then if b.submit_hash<>submission_hash then raise exception 'This answer is already committed' using errcode='40001';end if;return private.learning_session(p_slug,p_session);end if;
 perform private.resolve_execution(p_slug,p_session);select * into s from public.execution_sessions where id=p_session for update;
 if s.status='abandoned' or s.status='paused' then raise exception 'Resume the session before submitting' using errcode='22023';end if;
 expired:=s.status='expired';if not expired and s.version is distinct from p_version then raise exception 'Session changed; refresh before submitting' using errcode='40001';end if;
 select * into a from public.learning_activities where id=b.activity_id and version=b.activity_version;select * into k from private.learning_answer_keys where activity_id=a.id and activity_version=a.version;
 if k.activity_id is null then raise exception 'Answer evaluation unavailable' using errcode='22023';end if;
 if a.activity_type='numeric_answer' then
  if jsonb_typeof(p_answer)<>'number' then raise exception 'Enter a numeric answer' using errcode='22023';end if;
  answer_correct:=abs((p_answer#>>'{}')::numeric-(k.answer#>>'{}')::numeric)<=k.tolerance;
 elsif a.activity_type in ('ordering','multiple_select','matching') then
  if jsonb_typeof(p_answer)<>'array' or jsonb_array_length(p_answer)>20 then raise exception 'Choose a valid answer sequence' using errcode='22023';end if;
  if a.activity_type='multiple_select' then answer_correct:=(select jsonb_agg(value order by value) from jsonb_array_elements(p_answer))=(select jsonb_agg(value order by value) from jsonb_array_elements(k.answer));else answer_correct:=p_answer=k.answer;end if;
 else
  if jsonb_typeof(p_answer)<>'string' or not a.options @> jsonb_build_array(p_answer) then raise exception 'Choose an available option' using errcode='22023';end if;answer_correct:=p_answer=k.answer;
 end if;
 answer_correct:=answer_correct and not expired;
 update public.learning_execution_bindings set answer=case when expired then null else p_answer end,confidence=p_confidence,submitted_at=now(),correct=answer_correct,timed_out=expired,submit_hash=submission_hash where session_id=p_session;
 if s.status='active' then response:=private.mutate_execution(p_slug,s.id,s.version,gen_random_uuid(),jsonb_build_object('kind','finish'));end if;
 select * into s from public.execution_sessions where id=p_session;
 select id into aid from public.question_attempts where item_id=b.item_id;
 response:=private.mutate_execution(p_slug,s.id,s.version,gen_random_uuid(),jsonb_build_object('kind','debrief','attemptId',aid,'result',case when answer_correct then 'solved_independently' else 'could_not_solve' end,'confidence',p_confidence,'approach','','patternId',null,'timeComplexity','','spaceComplexity','','mistakes',to_jsonb(p_mistakes),'notes','Server-evaluated learning activity v'||a.version::text));
 return private.learning_session(p_slug,p_session);
end $$;
create function private.learning_evidence_guard() returns trigger language plpgsql security definer set search_path='' as $$declare b public.learning_execution_bindings%rowtype;begin
 if new.reflection_status='completed' then select * into b from public.learning_execution_bindings where item_id=new.item_id;
 if b.item_id is not null and (b.submitted_at is null or new.result<>case when b.correct then 'solved_independently' else 'could_not_solve' end or new.confidence<>b.confidence) then raise exception 'Submit this learning activity through its evaluator' using errcode='22023';end if;end if;return new;end $$;
revoke all on function private.learning_evidence_guard() from public,anon,authenticated,service_role;
create trigger learning_evidence_validation before insert or update on public.question_attempts for each row execute function private.learning_evidence_guard();

create function private.learning_overview(p_slug text) returns jsonb language plpgsql security definer set search_path='' as $$declare w public.workspaces%rowtype;begin
 w:=private.revision_access(p_slug);return jsonb_build_object('workspaceId',w.id,
 'opened',(select count(*) from public.workspace_learning_state where workspace_id=w.id and user_id=(select auth.uid())),
 'bookmarks',(select count(*) from public.workspace_learning_state where workspace_id=w.id and user_id=(select auth.uid()) and bookmarked),
 'attempts',(select count(*) from public.learning_execution_bindings where workspace_id=w.id and user_id=(select auth.uid()) and submitted_at is not null),
 'correct',(select count(*) from public.learning_execution_bindings where workspace_id=w.id and user_id=(select auth.uid()) and correct),
 'subjects',coalesce((select jsonb_agg(to_jsonb(x)) from(select t.subject_id,count(distinct s.concept_id) as opened,count(distinct s.concept_id) filter(where s.bookmarked) as bookmarks from public.workspace_learning_state s join public.learning_concepts c on c.id=s.concept_id and c.version=s.concept_version join public.learning_topic_catalog t on t.topic_id=c.topic_id where s.workspace_id=w.id and s.user_id=(select auth.uid()) group by t.subject_id) x),'[]'),
 'continue',coalesce((select jsonb_agg(to_jsonb(x)) from(select s.concept_id,c.name,t.subject_id,s.bookmarked,s.opened_at from public.workspace_learning_state s join public.learning_concepts c on c.id=s.concept_id and c.version=s.concept_version join public.learning_topic_catalog t on t.topic_id=c.topic_id where s.workspace_id=w.id and s.user_id=(select auth.uid()) order by s.opened_at desc limit 5) x),'[]'),
 'due',coalesce((select jsonb_agg(to_jsonb(x)) from(select r.id,c.name,c.id as concept_id,r.due_at,r.interval_days from public.revision_items r join public.learning_execution_bindings b on b.item_id=r.entity_id join public.learning_activities a on a.id=b.activity_id and a.version=b.activity_version join public.learning_concepts c on c.id=a.concept_id and c.version=a.concept_version where r.workspace_id=w.id and r.user_id=(select auth.uid()) and r.state in ('scheduled','snoozed') and r.due_at<=now() order by r.due_at limit 8) x),'[]'));
end $$;

-- Public invoker wrappers expose only authenticated, scope-checked contracts.
create function public.learning_catalog(p_slug text,p_subject text default 'aptitude',p_topic text default null,p_search text default '',p_after text default '',p_bookmarked boolean default false) returns jsonb language sql security invoker set search_path='' as $$select private.learning_catalog(p_slug,p_subject,p_topic,p_search,p_after,p_bookmarked)$$;
create function public.learning_concept(p_slug text,p_id text) returns jsonb language sql security invoker set search_path='' as $$select private.learning_concept(p_slug,p_id)$$;
create function public.learning_state(p_slug text,p_id text,p_version integer,p_request uuid,p_patch jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.learning_state(p_slug,p_id,p_version,p_request,p_patch)$$;
create function public.learning_session(p_slug text,p_session uuid) returns jsonb language sql security invoker set search_path='' as $$select private.learning_session(p_slug,p_session)$$;
create function public.learning_launch(p_slug text,p_activity text,p_mode text,p_request uuid) returns jsonb language sql security invoker set search_path='' as $$select private.learning_launch(p_slug,p_activity,p_mode,p_request)$$;
create function public.learning_submit(p_slug text,p_session uuid,p_version integer,p_answer jsonb,p_confidence integer,p_mistakes text[] default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.learning_submit(p_slug,p_session,p_version,p_answer,p_confidence,p_mistakes)$$;
create function public.learning_overview(p_slug text) returns jsonb language sql security invoker set search_path='' as $$select private.learning_overview(p_slug)$$;
do $$declare sig text;begin foreach sig in array array['learning_catalog(text,text,text,text,text,boolean)','learning_concept(text,text)','learning_state(text,text,integer,uuid,jsonb)','learning_session(text,uuid)','learning_launch(text,text,text,uuid)','learning_submit(text,uuid,integer,jsonb,integer,text[])','learning_overview(text)'] loop execute 'revoke all on function private.'||sig||' from public,anon,service_role';execute 'grant execute on function private.'||sig||' to authenticated';execute 'revoke all on function public.'||sig||' from public,anon,service_role';execute 'grant execute on function public.'||sig||' to authenticated';end loop;end $$;

-- Original editorial release 1. Planned coverage has no published lesson body.

create or replace function private.mastery_evidence(p_slug text,p_days integer default 90,p_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;evidence_json jsonb;begin
 w:=private.revision_access(p_slug);
 if p_days not in (7,30,90,365) or p_at>now() or p_at<now()-interval '400 days' then raise exception 'Choose a supported evidence window' using errcode='22023';end if;
 with base as materialized (
 select q.id,q.item_id,q.session_id,q.result,q.confidence,q.duration_ms,q.target_duration_ms,q.pattern_id,q.mistakes,q.completed_at,i.difficulty,i.title,
 coalesce(ri.entity_id,i.id) as learning_id,ta.topic_id,s.mode,
 ra.previous_interval_days is not null as is_revision,ra.previous_interval_days,ra.next_interval_days,
 extract(epoch from p_at-q.completed_at)/86400 as age_days
 from public.question_attempts q join public.execution_session_items i on i.id=q.item_id join public.execution_sessions s on s.id=q.session_id
 left join public.revision_execution_links rl on rl.item_id=i.id left join public.revision_items ri on ri.id=rl.revision_item_id
 left join public.execution_topic_attributions ta on ta.item_id=coalesce(ri.entity_id,i.id)
 left join public.revision_attempts ra on ra.source_attempt_id=q.id
 where q.workspace_id=w.id and q.user_id=(select auth.uid()) and q.reflection_status='completed' and q.completed_at>=p_at-make_interval(days=>p_days) and q.completed_at<=p_at and (q.duration_ms>=30000 or exists(select 1 from public.learning_execution_bindings lb where lb.item_id=q.item_id and lb.submitted_at is not null)) and s.status in ('completed','expired')
 ),expanded as materialized (
 select b.*,'topic'::text as entity_type,b.topic_id as entity_id from base b where b.topic_id is not null
 union all select b.*,'pattern',b.pattern_id from base b where b.pattern_id is not null
 ),bands as (
 select entity_type,entity_id,case when age_days<=14 then 'recent' when age_days<=45 then 'relevant' when age_days<=90 then 'historical' else 'archive' end as band,
 count(*) filter(where not is_revision) as initial_count,count(*) filter(where not is_revision and result='solved_independently') as initial_independent,
 count(*) filter(where is_revision) as review_count,count(*) filter(where is_revision and result='solved_independently') as review_independent,
 count(*) as total,count(*) filter(where result='solved_small_hint') as minor,count(*) filter(where result='solved_major_hint') as major,count(*) filter(where result='could_not_solve') as failed
 from expanded group by 1,2,3
 ),groups as (
 select e.entity_type,e.entity_id,count(*) as attempts,count(*) filter(where not e.is_revision) as initial_attempts,count(distinct e.learning_id) as distinct_entities,
 count(distinct (e.completed_at at time zone w.timezone)::date) as active_days,min(e.completed_at) as first_at,max(e.completed_at) as last_at,
 count(*) filter(where e.is_revision) as reviews,count(*) filter(where e.is_revision and e.result='solved_independently') as retained,
 count(*) filter(where e.age_days<=14 and e.result='solved_independently') as recent_independent,count(*) filter(where e.age_days<=14 and e.is_revision) as recent_reviews,
 jsonb_build_object('easy',count(*) filter(where difficulty='easy'),'medium',count(*) filter(where difficulty='medium'),'hard',count(*) filter(where difficulty='hard'),'unspecified',count(*) filter(where difficulty='unspecified')) as difficulty,
 jsonb_build_object('count',count(*) filter(where mode='interview' and result='solved_independently' and target_duration_ms>0 and duration_ms::numeric/target_duration_ms between 0.25 and 4),
 'medianRatio',percentile_cont(0.5) within group(order by duration_ms::numeric/nullif(target_duration_ms,0)) filter(where mode='interview' and result='solved_independently' and target_duration_ms>0 and duration_ms::numeric/target_duration_ms between 0.25 and 4),
 'outliers',count(*) filter(where mode='interview' and result='solved_independently' and target_duration_ms>0 and duration_ms::numeric/target_duration_ms not between 0.25 and 4)) as timing,
 percentile_cont(0.5) within group(order by duration_ms) as median_duration_ms,
 jsonb_build_object('recognition',count(*) filter(where 'recognition'=any(mistakes)),'edge_case',count(*) filter(where 'edge_case'=any(mistakes)),'complexity',count(*) filter(where 'complexity'=any(mistakes)),
 'recognition_entities',count(distinct learning_id) filter(where 'recognition'=any(mistakes)),'edge_case_entities',count(distinct learning_id) filter(where 'edge_case'=any(mistakes)),'complexity_entities',count(distinct learning_id) filter(where 'complexity'=any(mistakes))) as reported_mistakes,
 (select jsonb_agg(to_jsonb(b)-'entity_id'-'entity_type') from bands b where b.entity_type=e.entity_type and b.entity_id=e.entity_id) as buckets,
 (select jsonb_agg(to_jsonb(c)) from(select confidence,result,count(*) as count from expanded c where c.entity_type=e.entity_type and c.entity_id=e.entity_id and confidence is not null group by confidence,result) c) as confidence_pairs,
 (select r.id from public.revision_items r join public.execution_topic_attributions a on a.item_id=r.entity_id where r.workspace_id=w.id and r.user_id=(select auth.uid()) and r.state in ('scheduled','snoozed') and r.due_at<=p_at and ((e.entity_type='topic' and a.topic_id=e.entity_id) or (e.entity_type='pattern' and exists(select 1 from public.question_attempts z where z.item_id=r.entity_id and z.pattern_id=e.entity_id))) order by r.due_at,r.id limit 1) as due_revision_id
 from expanded e group by e.entity_type,e.entity_id
 ) select jsonb_build_object('groups',coalesce((select jsonb_agg(to_jsonb(g) order by g.entity_type,g.entity_id) from(select * from groups order by entity_type,entity_id limit 401) g),'[]'),
 'unmapped',jsonb_build_object('count',(select count(distinct learning_id) from base where topic_id is null),'items',coalesce((select jsonb_agg(to_jsonb(u)) from(select distinct on (learning_id) learning_id as item_id,title from base where topic_id is null order by learning_id limit 20) u),'[]')),
 'totals',jsonb_build_object('attempts',(select count(*) from base),'revisions',(select count(*) from base where is_revision),'retained',(select count(*) from base where is_revision and result='solved_independently')),
 'areas',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'trackId',t.track_id,'trackName',tr.name)) from public.learning_topic_catalog lc join public.topics t on t.id=lc.topic_id join public.tracks tr on tr.id=t.track_id where private.execution_topic_allowed(w.id,t.id)),'[]'),'asOf',p_at,'workspaceId',w.id,'userId',(select auth.uid())) into evidence_json;
 return evidence_json;
end $$;
;

create or replace function private.mastery_spine(p_slug text,p_type text,p_entity text,p_before jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;evidence_json jsonb;begin
 w:=private.revision_access(p_slug);
 if p_type not in ('topic','pattern') or length(p_entity)>120 or octet_length(coalesce(p_before::text,''))>500 then raise exception 'Invalid evidence selection' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(v) order by v.completed_at desc,v.id desc),'[]') into evidence_json from (
 select q.id,q.session_id,q.completed_at,q.result,q.confidence,q.duration_ms,i.title,i.difficulty,ra.previous_interval_days,ra.next_interval_days
 from public.question_attempts q join public.execution_session_items i on i.id=q.item_id
 left join public.revision_execution_links rl on rl.item_id=i.id left join public.revision_items ri on ri.id=rl.revision_item_id
 left join public.execution_topic_attributions a on a.item_id=coalesce(ri.entity_id,i.id) left join public.revision_attempts ra on ra.source_attempt_id=q.id
 where q.workspace_id=w.id and q.user_id=(select auth.uid()) and q.reflection_status='completed' and (q.duration_ms>=30000 or exists(select 1 from public.learning_execution_bindings lb where lb.item_id=q.item_id and lb.submitted_at is not null)) and ((p_type='topic' and a.topic_id=p_entity) or (p_type='pattern' and q.pattern_id=p_entity))
 and (p_before is null or (q.completed_at,q.id)<((p_before->>'at')::timestamptz,(p_before->>'id')::uuid)) order by q.completed_at desc,q.id desc limit 31
 ) v;return evidence_json;
end $$;
;
